trait Drawable { def draw(out: java.io.PrintStream): Unit }

given Drawable with                              // bind an unrelated type to the behaviour
  def draw(out: java.io.PrintStream): Unit = out.println("widget")

// erased abstract types need a witness to be tested at run time
def count[T](xs: List[Any])(using tt: TypeTest[Any, T]): Int =
  xs.count { case tt(_) => true; case _ => false }

count[String](List("a", 1, "b"))                   // 2
